//! Shared Original expression Debug projection over caller-borrowed typed facts.
//! Output DATA only: this formatter never parses, acquires source, or issues
//! expression/Original/currentness authority. Actual owners bind every loan.
use dm_syntax::{SettingAdmission,Span,OriginalTokenValue};
use std::io;
#[derive(Clone,Copy)]pub struct Text<'a>(pub &'a str);
impl Text<'_>{pub fn get(&self)->&str{self.0}}
#[derive(Clone,Copy)]pub struct Origin{pub file_key:usize,pub line:usize,pub byte_column:Option<usize>}
pub struct Token<'a>{pub span:Span,pub value:OriginalTokenValue<Text<'a>>,pub origin:Origin}
#[derive(Clone,Copy)]pub enum DebugSupport{Complete,Unissued(&'static str)}
pub trait Tokens{
 fn checkpoint(&self)->io::Result<()>;
 fn admission(&self)->&SettingAdmission<'_>;
 fn len(&self)->usize;
 fn token(&self,index:usize)->io::Result<Token<'_>>;
}
struct Rows<'a,T:Tokens>{source:&'a T,index:usize}
impl<'a,T:Tokens>Iterator for Rows<'a,T>{type Item=io::Result<Token<'a>>;fn next(&mut self)->Option<Self::Item>{if self.index>=self.source.len(){None}else{let index=self.index;self.index+=1;Some(self.source.token(index))}}}
pub(crate) struct Writer<'a,'op,T:Tokens>{source:&'a T,a:&'a SettingAdmission<'op>}
macro_rules! debug_step{($call:expr)=>{match $call?{DebugSupport::Complete=>(),unissued=>return Ok(unissued)}}}
impl<'a,T:Tokens>Writer<'a,'a,T>{pub(crate) fn new(source:&'a T)->Self{Self{source,a:source.admission()}}}
impl<'a,'op,T:Tokens>Writer<'a,'op,T>{
 fn check(&self)->io::Result<()>{self.source.checkpoint()}
 fn rows(&self)->Rows<'_,T>{Rows{source:self.source,index:0}}
 fn debug_row_at_start(&self,start:usize)->io::Result<Token<'_>>{self.check()?;for row in self.rows(){let row=row?;self.check()?;if row.span.start==start{return Ok(row)}}Err(io::ErrorKind::InvalidData.into())}
 fn debug_location(&self,row:&Token<'_>,out:&mut crate::macro_expansion::OriginalMacroText,file:&mut dyn FnMut(usize)->io::Result<u32>)->io::Result<()>{self.check()?;let id=file(row.origin.file_key)?;let column=row.origin.byte_column.ok_or_else(||io::Error::new(io::ErrorKind::Unsupported,"actual Original Debug token has no raw column loan"))?;crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"Location {{ file: FileId({id}), line: {}, column: {} }}",row.origin.line,column)})}
 /// Borrow actual AST+typed token rows; no constant folding/relex/new AST.
 pub(super) fn write_expression_debug_using(&self,expr:&dm_syntax::Expr,out:&mut crate::macro_expansion::OriginalMacroText,file:&mut dyn FnMut(usize)->io::Result<u32>)->io::Result<DebugSupport>{
  self.check()?;let _frame=self.a.evaluation_frame().map_err(|error|self.a.take_operational_error().unwrap_or(error))?;
  match &expr.kind{
   dm_syntax::ExprKind::Binary{op,lhs,rhs}=>{let(op,assignment)=match op.as_str(){"+"=>("Add",false),"-"=>("Sub",false),"*"=>("Mul",false),"/"=>("Div",false),"**"=>("Pow",false),"%"=>("Mod",false),"%%"=>("FloatMod",false),"=="=>("Eq",false),"!="=>("NotEq",false),"<"=>("Less",false),">"=>("Greater",false),"<="=>("LessEq",false),">="=>("GreaterEq",false),"<=>"=>("LessOrGreater",false),"~="=>("Equiv",false),"~!"=>("NotEquiv",false),"&"=>("BitAnd",false),"^"=>("BitXor",false),"|"=>("BitOr",false),"<<"=>("LShift",false),">>"=>("RShift",false),"&&"=>("And",false),"||"=>("Or",false),"in"=>("In",false),"to"=>("To",false),"="=>("Assign",true),"+="=>("AddAssign",true),"-="=>("SubAssign",true),"*="=>("MulAssign",true),"/="=>("DivAssign",true),"%="=>("ModAssign",true),"%%="=>("FloatModAssign",true),":="=>("AssignInto",true),"&="=>("BitAndAssign",true),"&&="=>("AndAssign",true),"|="=>("BitOrAssign",true),"||="=>("OrAssign",true),"^="=>("BitXorAssign",true),"<<="=>("LShiftAssign",true),">>="=>("RShiftAssign",true),_=>return Ok(DebugSupport::Unissued("actual Original expression Debug binary product is not issued"))};out.push_str(if assignment{"AssignOp { op: "}else{"BinaryOp { op: "},self.a)?;out.push_str(op,self.a)?;out.push_str(", lhs: ",self.a)?;debug_step!(self.write_expression_debug_using(lhs,out,file));out.push_str(", rhs: ",self.a)?;debug_step!(self.write_expression_debug_using(rhs,out,file));out.push_str(" }",self.a)?;},
   dm_syntax::ExprKind::Conditional{condition,then_value,else_value}=>{out.push_str("TernaryOp { cond: ",self.a)?;debug_step!(self.write_expression_debug_using(condition,out,file));out.push_str(", if_: ",self.a)?;debug_step!(self.write_expression_debug_using(then_value,out,file));out.push_str(", else_: ",self.a)?;debug_step!(self.write_expression_debug_using(else_value,out,file));out.push_str(" }",self.a)?;},
   _=>{let mut term=expr;loop{self.check()?;match &term.kind{dm_syntax::ExprKind::Unary{op,value}if matches!(op.as_str(),"-"|"!"|"~"|"&"|"*"|"pre++"|"pre--"|"post++"|"post--")=>term=value,dm_syntax::ExprKind::Member{object,..}|dm_syntax::ExprKind::SafeMember{object,..}|dm_syntax::ExprKind::StaticMember{object,..}|dm_syntax::ExprKind::Index{object,..}|dm_syntax::ExprKind::SafeIndex{object,..}=>term=object,_=>break}}out.push_str("Base { term: Spanned { location: ",self.a)?;debug_step!(self.write_debug_term(term,out,file));out.push_str(" }, follow: [",self.a)?;let mut first=true;debug_step!(self.write_debug_unary_follows(expr,out,file,&mut first));out.push_str("] }",self.a)?;}
  }Ok(DebugSupport::Complete)
 }
 fn write_debug_unary_follows(&self,expr:&dm_syntax::Expr,out:&mut crate::macro_expansion::OriginalMacroText,file:&mut dyn FnMut(usize)->io::Result<u32>,first:&mut bool)->io::Result<DebugSupport>{self.check()?;let _frame=self.a.evaluation_frame().map_err(|error|self.a.take_operational_error().unwrap_or(error))?;if matches!(&expr.kind,dm_syntax::ExprKind::Member{..}|dm_syntax::ExprKind::SafeMember{..}|dm_syntax::ExprKind::StaticMember{..}|dm_syntax::ExprKind::Index{..}|dm_syntax::ExprKind::SafeIndex{..}){return self.write_debug_attached_follow(expr,out,file,first)}let dm_syntax::ExprKind::Unary{op,value}=&expr.kind else{return Ok(DebugSupport::Complete)};let(kind,punct,post)=match op.as_str(){"-"=>("Neg","-",false),"!"=>("Not","!",false),"~"=>("BitNot","~",false),"&"=>("Reference","&",false),"*"=>("Dereference","*",false),"pre++"=>("PreIncr","++",false),"pre--"=>("PreDecr","--",false),"post++"=>("PostIncr","++",true),"post--"=>("PostDecr","--",true),_=>return Ok(DebugSupport::Complete)};debug_step!(self.write_debug_unary_follows(value,out,file,first));let row=if post{let mut row=None;for candidate in self.rows(){let candidate=candidate?;self.check()?;if candidate.span.end==expr.span.end{row=Some(candidate);break}}row.ok_or(io::ErrorKind::InvalidData)?}else{self.debug_row_at_start(expr.span.start)?};if !matches!(row.value,OriginalTokenValue::Punct(actual)if actual==punct){return Err(io::ErrorKind::InvalidData.into())}if !*first{out.push_str(", ",self.a)?}*first=false;out.push_str("Spanned { location: ",self.a)?;self.debug_location(&row,out,file)?;out.push_str(", elem: Unary(",self.a)?;out.push_str(kind,self.a)?;out.push_str(") }",self.a)?;Ok(DebugSupport::Complete)}
 fn write_debug_attached_follow(&self,expr:&dm_syntax::Expr,out:&mut crate::macro_expansion::OriginalMacroText,file:&mut dyn FnMut(usize)->io::Result<u32>,first:&mut bool)->io::Result<DebugSupport>{
  let(object,index,selector,access)=match &expr.kind{dm_syntax::ExprKind::Member{object,selector,via_colon}=>(object.as_ref(),None,Some(selector.as_str()),if *via_colon{"Colon"}else{"Dot"}),dm_syntax::ExprKind::SafeMember{object,selector,via_colon}=>(object.as_ref(),None,Some(selector.as_str()),if *via_colon{"SafeColon"}else{"SafeDot"}),dm_syntax::ExprKind::StaticMember{object,selector}=>(object.as_ref(),None,Some(selector.as_str()),"Static"),dm_syntax::ExprKind::Index{object,index}=>(object.as_ref(),Some(index.as_ref()),None,"Normal"),dm_syntax::ExprKind::SafeIndex{object,index}=>(object.as_ref(),Some(index.as_ref()),None,"Safe"),_=>return Err(io::ErrorKind::InvalidData.into())};
  debug_step!(self.write_debug_unary_follows(object,out,file,first));
  let mut actual=None;for row in self.rows(){let row=row?;self.check()?;if row.span.start<object.span.end||row.span.start>=expr.span.end{continue}if matches!(row.value,OriginalTokenValue::Punct(" "|"\t"|"\n")){continue}actual=Some(row);break}let row=actual.ok_or(io::ErrorKind::InvalidData)?;
  let expected=match access{"Dot"=>".","Colon"=>":","SafeDot"=>"?.","SafeColon"=>"?:","Static"=>"::","Normal"=>"[","Safe"=>"?[",_=>return Err(io::ErrorKind::InvalidData.into())};if !matches!(row.value,OriginalTokenValue::Punct(op)if op==expected){return Ok(DebugSupport::Unissued("actual Original attached follow operator Debug product is not issued"))}
  if let Some(name)=selector{if !name.is_empty(){let mut bound=false;for candidate in self.rows(){let candidate=candidate?;self.check()?;if candidate.span.end==expr.span.end&&matches!(&candidate.value,OriginalTokenValue::Ident{spelling,..}if spelling.get()==name){bound=true;break}}if !bound{return Err(io::ErrorKind::InvalidData.into())}}}
  if !*first{out.push_str(", ",self.a)?;}*first=false;out.push_str("Spanned { location: ",self.a)?;self.debug_location(&row,out,file)?;out.push_str(", elem: ",self.a)?;
  if let Some(index)=index{out.push_str("Index(",self.a)?;out.push_str(access,self.a)?;out.push_str(", ",self.a)?;debug_step!(self.write_expression_debug_using(index,out,file));out.push(')',self.a)?;}else{let name=selector.ok_or(io::ErrorKind::InvalidData)?;crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;if access=="Static"{write!(out,"StaticField({name:?})")}else{write!(out,"Field({access}, {name:?})")}})?;}out.push_str(" }",self.a)?;Ok(DebugSupport::Complete)
 }
 fn write_debug_term(&self,expr:&dm_syntax::Expr,out:&mut crate::macro_expansion::OriginalMacroText,file:&mut dyn FnMut(usize)->io::Result<u32>)->io::Result<DebugSupport>{self.check()?;let row=self.debug_row_at_start(expr.span.start)?;match &expr.kind{
  dm_syntax::ExprKind::Literal(literal)=>{if row.span!=expr.span{if literal.as_str()=="null"&&literal.original_value().is_none()&&self.debug_empty_parentheses(expr)?{self.debug_location(&row,out,file)?;out.push_str(", elem: Null",self.a)?;return Ok(DebugSupport::Complete)}return Ok(DebugSupport::Unissued("actual non-scalar Original term Debug product is not issued"))}self.debug_location(&row,out,file)?;out.push_str(", elem: ",self.a)?;let value=row.value.map_text(|text|text.get());match (literal.original_value(),value){(Some(OriginalTokenValue::Int(wanted)),OriginalTokenValue::Int(actual))if wanted==actual=>crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"Int({actual:?})")})?,(Some(OriginalTokenValue::Float(wanted)),OriginalTokenValue::Float(actual))if wanted.to_bits()==actual.to_bits()=>crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"Float({actual:?})")})?,(Some(OriginalTokenValue::String(wanted)),OriginalTokenValue::String(actual))if wanted==actual=>crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"String({actual:?})")})?,(Some(OriginalTokenValue::Resource(wanted)),OriginalTokenValue::Resource(actual))if wanted==actual=>crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"Resource({actual:?})")})?,(None,OriginalTokenValue::Ident{spelling:"null",..})if literal.as_str()=="null"=>out.push_str("Null",self.a)?,_=>return Ok(DebugSupport::Unissued("actual typed Original scalar Debug binding is not issued"))}},
  dm_syntax::ExprKind::Ident(name)=>{if row.span!=expr.span||!matches!(&row.value,OriginalTokenValue::Ident{spelling,..}if spelling.get()==name){return Err(io::ErrorKind::InvalidData.into())}self.debug_location(&row,out,file)?;out.push_str(", elem: ",self.a)?;if matches!(name.as_str(),"__TYPE__"|"__IMPLIED_TYPE__"){out.push_str(name,self.a)?;}else{crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"Ident({name:?})")})?;}},
  dm_syntax::ExprKind::Call{callee,args}=>{let dm_syntax::ExprKind::Ident(name)=&callee.kind else{return Ok(DebugSupport::Unissued("actual Original dynamic/follow call term Debug product is not issued"))};if matches!(name.as_str(),"new"|"input"|"locate"|"pick"|"call"|"call_ext"|"__PROC__"|"__TYPE__"|"__IMPLIED_TYPE__"){return Ok(DebugSupport::Unissued("actual Original special call term Debug product is not issued"))}if row.span!=callee.span||!matches!(&row.value,OriginalTokenValue::Ident{spelling,..}if spelling.get()==name){return Err(io::ErrorKind::InvalidData.into())}self.debug_location(&row,out,file)?;out.push_str(", elem: ",self.a)?;if name=="list"{out.push_str("List([",self.a)?;}else{crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"Call({name:?}, [")})?;}for(index,arg)in args.iter().enumerate(){self.check()?;if index!=0{out.push_str(", ",self.a)?}debug_step!(self.write_expression_debug_using(arg,out,file));}out.push_str("])",self.a)?;},
  dm_syntax::ExprKind::TypePath(_)=>{self.debug_location(&row,out,file)?;out.push_str(", elem: Prefab(Prefab { path: ",self.a)?;debug_step!(self.write_debug_prefab_path(expr,out));out.push_str(", vars: [] })",self.a)?;},
  dm_syntax::ExprKind::ObjectInitializer{object,fields}=>{if !matches!(&object.kind,dm_syntax::ExprKind::TypePath(_)){return Ok(DebugSupport::Unissued("actual Original initializer Debug lacks prefab target"))}self.debug_location(&row,out,file)?;out.push_str(", elem: Prefab(Prefab { path: ",self.a)?;debug_step!(self.write_debug_prefab_path(object,out));out.push_str(", vars: [",self.a)?;for(index,(name,value))in fields.iter().enumerate(){self.check()?;if index!=0{out.push_str(", ",self.a)?;}crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"({name:?}, ")})?;debug_step!(self.write_expression_debug_using(value,out,file));out.push(')',self.a)?;}out.push_str("] })",self.a)?;},
  dm_syntax::ExprKind::Unary{op,value}if op=="::"=>{let dm_syntax::ExprKind::Ident(name)=&value.kind else{return Ok(DebugSupport::Unissued("actual Original global Debug name is not issued"))};if !matches!(row.value,OriginalTokenValue::Punct("::")){return Err(io::ErrorKind::InvalidData.into())}let actual=self.debug_row_at_start(value.span.start)?;if actual.span!=value.span||!matches!(&actual.value,OriginalTokenValue::Ident{spelling,..}if spelling.get()==name){return Err(io::ErrorKind::InvalidData.into())}self.debug_location(&row,out,file)?;out.push_str(", elem: ",self.a)?;crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"GlobalIdent({name:?})")})?;},
  dm_syntax::ExprKind::Group(inner)=>{if !matches!(row.value,OriginalTokenValue::Punct("(")){return Err(io::ErrorKind::InvalidData.into())}self.debug_location(&row,out,file)?;out.push_str(", elem: Expr(",self.a)?;debug_step!(self.write_expression_debug_using(inner,out,file));out.push(')',self.a)?;},
  _=>return Ok(DebugSupport::Unissued("actual Original compound term/follow Debug product is not issued")),
 }Ok(DebugSupport::Complete)}
 fn debug_empty_parentheses(&self,expr:&dm_syntax::Expr)->io::Result<bool>{let mut seen=0;for row in self.rows(){let row=row?;self.check()?;if row.span.start<expr.span.start||row.span.end>expr.span.end{continue}if matches!(row.value,OriginalTokenValue::Punct(" "|"\t"|"\n")){continue}let expected=if seen==0{"("}else{")"};if seen>=2||!matches!(row.value,OriginalTokenValue::Punct(actual)if actual==expected){return Ok(false)}seen+=1;}Ok(seen==2)}
 fn write_debug_prefab_path(&self,expr:&dm_syntax::Expr,out:&mut crate::macro_expansion::OriginalMacroText)->io::Result<DebugSupport>{out.push('[',self.a)?;let mut operator=None;let mut count=0;for row in self.rows(){let row=row?;self.check()?;if row.span.start<expr.span.start||row.span.end>expr.span.end{continue}match &row.value{OriginalTokenValue::Punct(" "|"\t"|"\n")=>(),OriginalTokenValue::Punct(op @ ("/"|"."|":"))=>operator=Some(match *op{"/"=>"Slash","."=>"Dot",_=>"Colon"}),OriginalTokenValue::Ident{spelling,..}=>{let Some(op)=operator.take()else{return Ok(DebugSupport::Unissued("actual Original prefab path Debug component operator is unissued"))};if count!=0{out.push_str(", ",self.a)?;}let name=spelling.get();crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"({op}, {name:?})")})?;count+=1;},_=>return Ok(DebugSupport::Unissued("actual Original prefab path Debug token product is not issued"))}}if count==0||operator.is_some(){return Ok(DebugSupport::Unissued("actual Original root/trailing prefab Debug product is not issued"))}out.push(']',self.a)?;Ok(DebugSupport::Complete)}

}

/// Paid text DATA only. Complete denotes formatter coverage, never parser,
/// Original profile, current source, EOF or initializer ownership authority.
pub struct Formatted{support:DebugSupport,text:crate::macro_expansion::OriginalMacroText}
impl Formatted{pub fn support(&self)->DebugSupport{self.support}pub fn as_str(&self)->&str{self.text.as_str()}}
pub fn format_using(source:&impl Tokens,expr:&dm_syntax::Expr,file:&mut dyn FnMut(usize)->io::Result<u32>)->io::Result<Formatted>{
 let a=source.admission();let pending=(||{let mut text=crate::macro_expansion::OriginalMacroText::new(a)?;let support=Writer::new(source).write_expression_debug_using(expr,&mut text,file)?;Ok(Formatted{support,text})})();
 match a.take_operational_error(){Some(first)=>Err(first),None=>pending}
}


/// Exact Expression::from(VarSuffix::into_initializer()) Debug projection.
/// This is derived formatter DATA; caller binds the real authored suffix/roots.
pub struct ImplicitArray{out:crate::macro_expansion::OriginalMacroText,count:usize,next:usize}
impl ImplicitArray{
 pub fn new(count:usize,a:&dm_syntax::SettingAdmission<'_>)->io::Result<Self>{let pending=(||{if count==0{return Err(io::ErrorKind::InvalidInput.into())}let mut out=crate::macro_expansion::OriginalMacroText::new(a)?;out.push_str("Base { term: Spanned { location: Location { file: FileId(65535), line: 0, column: 0 }, elem: NewPrefab { prefab: Prefab { path: [(Slash, \"list\")], vars: [] }, args: Some([",a)?;Ok(Self{out,count,next:0})})();match a.take_operational_error(){Some(first)=>Err(first),None=>pending}}
 pub fn push(&mut self,root:Formatted,a:&dm_syntax::SettingAdmission<'_>)->io::Result<()>{let pending=(||{if self.next>=self.count||!matches!(root.support,DebugSupport::Complete){return Err(io::ErrorKind::Unsupported.into())}if self.next!=0{self.out.push_str(", ",a)?;}self.out.push_str(root.as_str(),a)?;self.next+=1;Ok(())})();match a.take_operational_error(){Some(first)=>Err(first),None=>pending}}
 pub fn finish(mut self,a:&dm_syntax::SettingAdmission<'_>)->io::Result<Formatted>{let pending=(||{if self.next!=self.count{return Err(io::ErrorKind::InvalidInput.into())}self.out.push_str("]) } }, follow: [] }",a)?;Ok(Formatted{support:DebugSupport::Complete,text:self.out})})();match a.take_operational_error(){Some(first)=>Err(first),None=>pending}}
}
